script:
# ==========================================
# PART 1: ADMIN OFFICER (AO) PERMISSIONS
# ==========================================

# 1. HANDLE AO REMOVAL / CHANGE (Clean up old permission)
# Get the previous AO value from the database before this save
old_ao = doc.get_db_value("custom_administrative_officer")

# If the AO changed or was removed, delete the old permission
if old_ao and old_ao != doc.custom_administrative_officer:
    old_ao_user = frappe.db.get_value("Employee", old_ao, "user_id")

    if old_ao_user:
        permission_name = frappe.db.get_value(
            "User Permission",
            {
                "user": old_ao_user,
                "allow": "Employee",
                "for_value": doc.name,
            },
            "name"
        )

        if permission_name:
            frappe.get_doc("User Permission", permission_name).delete()

# 2. HANDLE NEW AO ASSIGNMENT (Apply new permission)
if doc.custom_administrative_officer:
    # Fetch the User ID of the newly assigned AO
    new_ao_user = frappe.db.get_value("Employee", doc.custom_administrative_officer, "user_id")

    if new_ao_user:
        # Verify if the permission already exists to avoid duplicates
        permission_exists = frappe.db.exists("User Permission", {
            "user": new_ao_user,
            "allow": "Employee",
            "for_value": doc.name
        })

        # Create the new permission if it doesn't exist
        if not permission_exists:
            frappe.get_doc({
                "doctype": "User Permission",
                "user": new_ao_user,
                "allow": "Employee",
                "for_value": doc.name,
                "apply_to_all_doctypes": 1
            }).insert()


# ==========================================
# PART 2: HEAD OF DEPARTMENT (HOD) PERMISSIONS
# ==========================================

# 3. HANDLE HOD REMOVAL / CHANGE (Clean up old permission)
# Get the previous HOD value from the database before this save
old_hod = doc.get_db_value("custom_hod")

# If the HOD changed or was removed, delete the old permission
if old_hod and old_hod != doc.custom_hod:
    old_hod_user = frappe.db.get_value("Employee", old_hod, "user_id")

    if old_hod_user:
        hod_permission_name = frappe.db.get_value(
            "User Permission",
            {
                "user": old_hod_user,
                "allow": "Employee",
                "for_value": doc.name,
            },
            "name"
        )

        if hod_permission_name:
            frappe.get_doc("User Permission", hod_permission_name).delete()

# 4. HANDLE NEW HOD ASSIGNMENT (Apply new permission)
if doc.custom_hod:
    # Fetch the User ID of the newly assigned HOD
    new_hod_user = frappe.db.get_value("Employee", doc.custom_hod, "user_id")

    if new_hod_user:
        # Verify if the permission already exists to avoid duplicates
        hod_permission_exists = frappe.db.exists("User Permission", {
            "user": new_hod_user,
            "allow": "Employee",
            "for_value": doc.name
        })

        # Create the new permission if it doesn't exist
        if not hod_permission_exists:
            frappe.get_doc({
                "doctype": "User Permission",
                "user": new_hod_user,
                "allow": "Employee",
                "for_value": doc.name,
                "apply_to_all_doctypes": 1
            }).insert()
# 5. HANDLE BRANCH REMOVAL / CHANGE
# Assumes 'branch' is the fieldname in the current DocType
old_branch = doc.get_db_value("branch") 

if old_branch and old_branch != doc.branch:
    # We need a user to assign the permission to. 
    # Usually, this requires a specific user linked to the branch, 
    # or you may be applying this to the logged-in user or a specific role.
    # Assuming you want to grant access to the User set in the Employee record for this branch:
    target_user = frappe.db.get_value("Employee", doc.name, "user_id")

    if target_user:
        permission_name = frappe.db.get_value(
            "User Permission",
            {
                "user": target_user,
                "allow": "Branch",
                "for_value": old_branch,
            },
            "name"
        )

        if permission_name:
            frappe.get_doc("User Permission", permission_name).delete()

# 6. HANDLE NEW BRANCH ASSIGNMENT
if doc.branch:
    target_user = frappe.db.get_value("Employee", doc.name, "user_id")

    if target_user:
        # Check if permission exists
        branch_permission_exists = frappe.db.exists("User Permission", {
            "user": target_user,
            "allow": "Branch",
            "for_value": doc.branch
        })

        if not branch_permission_exists:
            frappe.get_doc({
                "doctype": "User Permission",
                "user": target_user,
                "allow": "Branch",
                "for_value": doc.branch,
                "apply_to_all_doctypes": 1
            }).insert()
